INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13245, 'koKR', 'Dowód zgonu: Ingvar Łupieżca', 'Zbierz drużynę i poprowadź ją do Twierdzy Utgard. Masz tam odnaleźć i zabić Ingvara Łupieżcę, zanim poprowadzi swoje wrykulskie siły, by złupić pobliskie osady Przymierza i Hordy.$B$BPotrzebuję jego topora jako dowodu, że się z nim rozprawiono. Nie chodzi o to, że ci nie ufam. Po prostu roztropnie jest mieć pewność, że rzecz została zrobiona.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Toporem Łupieżcy.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13246, 'koKR', 'Dowód zgonu: Keristrasza', 'Znasz historię Keristraszy?$B$BWiesz, jak przyczyniła się do zgładzenia Saragosy, małżonki Malygosa? I jak on w zamian wziął Keristraszę za swoją małżonkę, zamrażając ją w bryle lodu?$B$BDowiedzieliśmy się, że Malygos łamie jej wolę swoją magią. Doprowadziło ją to do obłędu.$B$B$N, musisz udać się do Nexusa w Mrozarze i położyć jej kres, zanim zostanie całkowicie przeciągnięta na jego stronę.$B$BChoć to mnie smuci, muszę nalegać, byś $gprzyniósł:przyniosła; mi jej serce jako dowód.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; ze złamanym sercem Keristraszy.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13247, 'koKR', 'Dowód zgonu: Strażnik Linii Mocy Eregos', 'Wojna o Nexus wciąż szaleje, a my musimy coś zrobić, by odwrócić losy walki! Czy zechcesz polecieć w samo serce bitwy, $N?$B$BStrażnik Linii Mocy Eregos chroni kanał, którym Malygos odprowadza magiczną moc linii mocy Azeroth. Jeśli uda się go zabić, będzie to potężny cios dla wroga.$B$BPrzynieś mi, proszę, jeden z jego stroików linii mocy, byśmy mogli go zbadać.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; ze stroikiem linii mocy.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13248, 'koKR', 'Dowód zgonu: Król Ymiron', 'Król Ymiron z Iglicy Utgard jest ulubionym wrykulem Króla Lisza. Już samo to wystarczy, by z nim skończyć.$B$BLecz jeśli zadmie w rogi i wezwie wszystkich przywódców zarówno Ymirjarów, jak i Mjordinów, wrykule staną się potęgą większą niż jakakolwiek inna w szeregach Plagi!$B$BTo od ciebie, $N, zależy, czy do tego nie dojdzie. Przynieś mi medalion z jego szyi, żebym wiedział, że Ymiron nie stanowi już zagrożenia.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Medalionem zmarłej królowej.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13249, 'koKR', 'Dowód zgonu: Prorok Tharon\'ja', 'Twierdza Drak\'Tharon była niegdyś dumnym bastionem narodu Drakkari. Teraz to tylko przyczółek Króla Lisza w walce, która ma położyć kres Zul\'Drakowi i wydrzeć moc trollowym bogom.$B$BJeśli jednak zgładzimy ich przywódcę, Proroka Tharon\'ję, może zdołamy powstrzymać napływ trollowych posiłków Plagi. W najgorszym razie Krucjata Argentu w Zul\'Draku będzie miała o jedno zmartwienie mniej.$B$BPrzynieś mi jego tiki, żebym wiedział, że prorok nie żyje.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Zaczarowanym tiki proroka.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13250, 'koKR', 'Dowód zgonu: Gal\'darah', 'Prorocy Drakkarów z Zul\'Draku uczynili rzecz nie do pomyślenia: zabili większość swoich bogów, by wchłonąć ich moce! Najgroźniejszy z nich wszystkich to arcyprorok Akaliego, Gal\'darah.$B$BZaszyty w trzewiach Gundraku Gal\'darah wchłonął niemal całe mojo zabitego Akaliego i lada chwila wyleje się z miasta wraz ze swoimi wyznawcami. Jeśli nie zabijemy go teraz, zaleje nas morze szaleństwa i niewyobrażalnej mocy!$B$BSpiesz się, $N, przynieś mi to, co zostało z mojo Akaliego.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Resztką mojo Akaliego.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13251, 'koKR', 'Dowód zgonu: Mal\'Ganis', '$N, przyjaciel z Brązowego Stada przekazał mi informacje, które musimy wykorzystać.$B$BTajemnicze istoty z Płonącego Legionu zwane upiornymi władcami to rasa znana też jako nathrezimowie. Niewiele wiadomo o ich ojczystym świecie, a i to są tylko pogłoski.$B$BWiadomo jednak, że Mal\'Ganis z przeszłości popełnił poważny błąd: zostawił artefakt ze swojego ojczystego świata!$B$BMusisz cofnąć się przez Jaskinie Czasu do chwili znanej jako Rzeź Stratholmu. Odzyskaj ten artefakt.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; z artefaktem z ojczystego świata nathrezimów.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13252, 'koKR', 'Dowód zgonu: Sjonnir Kształtujący Żelazo', 'Niewiele wiadomo o przypadłości zwanej Klątwą Ciała. W Salach Kamienia można jednak znaleźć informacje na jej temat.$B$BSjonnir Kształtujący Żelazo zdaje się wiedzieć o tej klątwie bardzo wiele. Z pewnego źródła wiemy, że nosi przy sobie tytański dysk z informacjami, który mógłby odpowiedzieć na wszystkie nasze pytania.$B$BOdzyskaj dla mnie ten dysk, $N, abyśmy mogli poznać prawdę.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Dyskiem Klątwy Ciała.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13253, 'koKR', 'Dowód zgonu: Loken', 'W Salach Błyskawic Loken szykuje się, by położyć kres naszemu światu. Czy muszę mówić coś więcej, $N?$B$BSiedzi tam i słucha szalonych szeptów Przedwiecznego uwięzionego pod Północną Granią. Ty i twoi przyjaciele musicie natychmiast udać się na Burzowe Szczyty!$B$BStań do walki z Lokenem w Ziemskiej Strażnicy i powstrzymaj go, zanim będzie za późno! Przynieś mi jego rubinowy pierścień, abym wiedział, że znów jesteśmy bezpieczni.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z pierścieniem z niebiańskim rubinem.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13254, 'koKR', 'Dowód zgonu: Anub\'arak', 'Nerubianie przemienieni przez Plagę są zmorą naszych wojsk.$B$BTu, unosząc się nad światem, jesteśmy przed nimi bezpieczni, ale ilekroć stawiamy stopę na ziemi w dole, towarzyszy nam myśl, że nieumarli nerubianie mogą wygrzebać się z głębin Azjol-Nerub i zaatakować.$B$BW interesie wszystkich leży, by zapanował wśród nich chaos. Zabij ich dawnego króla, a dziś majordomusa Króla Lisza – lorda krypt Anub\'araka.$B$BPrzynieś mi, proszę, jego koronę... choć już jej nie nosi.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Bezczynną koroną Anub\'araka.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13255, 'koKR', 'Dowód zgonu: Herold Volazj', 'Nerubianie z Ahn\'kahet, próbując umknąć przed inwazją Plagi, dokopali się zbyt głęboko. Zbliżyli się za bardzo do Przedwiecznego spoczywającego pod Północną Granią.$B$BPrzebudzony Przedwieczny wysłał przeciw nim swoje obłąkane stwory i nerubianie znaleźli się, jak to mówią, między młotem a kowadłem.$B$BPrzywódca sił Przedwiecznych, herold Volazj, jest jedną z koszmarnych istot zwanych Beztwarzowymi. Połóż mu kres i przynieś mi jego zwiędły mózg.$B$BTylko proszę, postaraj się nie postradać zmysłów.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; ze zwiędłym mózgiem Beztwarzowego.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13256, 'koKR', 'Dowód zgonu: Cyjanigosa', 'Zostaliśmy najechani! Błękitne Stado teleportowało się do Purpurowej Twierdzy i planuje wyrwać się stamtąd do reszty Dalaranu!$B$BJuż są doniesienia, że przez ich działania więźniowie przypadkiem odzyskują wolność. Nie zdziwiłbym się, gdyby celowo wypuszczali niektórych z nich.$B$B$N, możesz szybko zebrać drużynę i się tam dostać? Cyjanigosa dowodzi ich siłami inwazyjnymi. Przynieś mi jej głowę!', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Głową Cyjanigosy.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(14199, 'koKR', 'Dowód zgonu: Czarny Rycerz', 'Mój odpowiednik, arcymag Timear, poprosił mnie, bym cię ostrzegł przed czymś groźnym. Wkrótce weźmiesz udział w Próbie Czempiona w Argentowym Koloseum w Lodowej Koronie. Strzeż się ingerencji kogoś, kogo znamy tylko jako Czarnego Rycerza.$B$BPrzynieś mi odłamek jego duszy, żeby Kirin Tor wiedział, że się z nim rozprawiono. Podobno jeśli tego nie zrobisz, ściągniesz na siebie zgubę.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Odłamkiem duszy Czarnego Rycerza.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13255, 'koKR', '<Arcymag ostrożnie przygląda się mózgowi.>$b$bTeraz, gdy o tym myślę, nie jestem pewien, czy przebywanie tak blisko tego czegoś jest bezpieczne. Mówisz, że to wciąż żyje?$b$b<Kręci głową.>$b$bMamy w cytadeli miejsce na takie rzeczy. Dopilnuję, by jeden z moich uczniów natychmiast je tam zaniósł.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13255, 'koKR', '$n? Wciąż przy zdrowych zmysłach?', 0);
