INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(30789, 'koKR', '', 'To święte komnaty! Za wtargnięcie czeka was śmierć!', 0),
(30862, 'koKR', '', 'Kto spośród was jest oddany?', 0),
(31699, 'koKR', '', 'Ty tam! Wystąp!', 0),
(31700, 'koKR', '', 'Yogg-Saronie! Obdarz mnie swą mocą!', 0),
(31701, 'koKR', '', 'Panie, dar dla ciebie!', 0),
(31702, 'koKR', '', 'Chwała Yogg-Saronowi!', 0),
(31703, 'koKR', '', 'Nie zasługujesz na to.', 0),
(31704, 'koKR', '', 'Wstawaj! Twoje cierpienie jeszcze się nie skończyło.', 0),
(31705, 'koKR', '', 'Nie myślcie, że wasze świętokradztwo... ujdzie wam bezkarnie.', 0),
(31706, 'koKR', '', 'Same żywioły powstaną przeciw cywilizowanemu światu! Oszczędzeni zostaną tylko wierni!', 0),
(31707, 'koKR', '', 'Nieśmiertelność może być twoja, ale tylko jeśli całkowicie oddasz się Yogg-Saronowi!', 0),
(31708, 'koKR', '', 'Tu, na samej granicy jego władztwa, zaznacie mocy, jakiej nigdy nie zdołalibyście sobie wyobrazić!', 0),
(31709, 'koKR', '', 'Przebyliście długą drogę i wiele zaryzykowaliście, by tu dotrzeć! Wasze oddanie zostanie nagrodzone.', 0),
(31710, 'koKR', '', 'Wierni zostaną wywyższeni, lecz wiele pracy jeszcze przed nami. Nie ustaniemy, dopóki całe Azeroth nie legnie w jego cieniu!', 0),
(31884, 'koKR', 'Sekrety głębin pozostaną ukryte.', '', 0),
(31886, 'koKR', 'Młode nie mogą głodować....', '', 0),
(31887, 'koKR', 'Shhhad ak kereeesshh chak-k-k!', '', 0),
(31888, 'koKR', 'Śpij teraz w zimnym mroku....', '', 0),
(31889, 'koKR', 'Za Króla Lisza!', '', 0),
(31890, 'koKR', 'Być może wkrótce będziemy sojusznikami.', '', 0),
(31891, 'koKR', 'Panie... czy moja służba... dobiegła końca?', '', 0),
(31894, 'koKR', 'Wykluwa się strażnik Ahn\'kahar!', '', 0),
(31895, 'koKR', 'Pożywię się waszymi szczątkami!', '', 0),
(31896, 'koKR', 'Bicie twego serca jest... muzyką dla moich uszu.', '', 0),
(31897, 'koKR', 'Jestem nigdzie.... Jestem wszędzie. Jestem niewidzialnym obserwatorem.', '', 0),
(31898, 'koKR', 'Jakie... apetyczne.', '', 0),
(31899, 'koKR', 'Świeża, ciepła krew... tak dawno jej nie kosztowałem.', '', 0),
(31901, 'koKR', 'Nie wypiję krwi przed czasem.', '', 0),
